import React from 'react';
import Seo from '../components/Seo';
import Icon from '../components/Icon';
import {capabilities} from '../data/site';
const icons=['device','phone','database','spark','layers','cpu','shield'];
export default function Expertise(){return <><Seo title="Compétences" path="/expertise" description="Compétences utilisées dans les projets Beyond31 : React, Flutter, Supabase, Firebase, UX, SEO technique, sécurité web et systèmes embarqués."/>
<section className="page-hero elegant-page"><p className="eyebrow"><span/>Compétences</p><h1>Du détail,<br/><em>sans se raconter d’histoires.</em></h1><p>Voici les domaines réellement pratiqués à travers les projets Beyond31. Le niveau évolue, la liste aussi.</p></section>
<section className="expertise-list">{capabilities.map((c,i)=><article className="expertise-row" key={c.n}><div className="expertise-icon"><Icon name={icons[i]}/></div><div><span>{c.n}</span><h2>{c.title}</h2><p>{c.desc}</p></div><div className="tool-cloud">{c.tools.map(t=><span key={t}>{t}</span>)}</div></article>)}</section>
<section className="expertise-note glass-wide"><Icon name="shield" size={24}/><div><h2>Qualité avant empilement.</h2><p>Structure sémantique, métadonnées propres, headers de sécurité, règles d’accès côté backend et dépendances limitées font partie du travail — même lorsque ça ne se voit pas sur une capture d’écran.</p></div></section>
</>}
